<?php
declare(strict_types=1);
const MEDIA_IMAGE_WIDTHS=[320,480,768,1024,1440,1920];
function media_upload_root():string{return dirname(__DIR__).'/uploads/media';}
function media_url(string $path):string{return '/uploads/media/'.ltrim(str_replace('\\','/',$path),'/');}
function media_capabilities():array{return ['imagick'=>extension_loaded('imagick'),'gd'=>extension_loaded('gd'),'ffmpeg'=>(bool)@shell_exec('ffmpeg -version 2>NUL'),'upload_max'=>ini_get('upload_max_filesize'),'post_max'=>ini_get('post_max_size'),'memory_limit'=>ini_get('memory_limit')];}
function media_safe_file(array $file):array{if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('upload_failed');if(($file['size']??0)>50*1024*1024)throw new RuntimeException('file_too_large');$f=new finfo(FILEINFO_MIME_TYPE);$mime=$f->file($file['tmp_name']);$types=['image/jpeg'=>'image','image/png'=>'image','image/webp'=>'image','video/mp4'=>'video','video/webm'=>'video'];if(!isset($types[$mime]))throw new RuntimeException('unsupported_or_invalid_file');return [$mime,$types[$mime]];}
function media_image_info(string $file):array{$i=@getimagesize($file);return $i?[(int)$i[0],(int)$i[1]]:[null,null];}
function media_create(PDO $db,array $file,?int $replaceAsset=null):array{[$mime,$kind]=media_safe_file($file);$now=gmdate('c');$assetUuid=bin2hex(random_bytes(16));$versionUuid=bin2hex(random_bytes(16));$checksum=hash_file('sha256',$file['tmp_name']);[$w,$h]=$kind==='image'?media_image_info($file['tmp_name']):[null,null];$asset=$replaceAsset?$db->prepare('SELECT * FROM media_assets WHERE id=?'):null;if($asset){$asset->execute([$replaceAsset]);$existing=$asset->fetch();if(!$existing)throw new RuntimeException('asset_not_found');if($existing['kind']!==$kind)throw new RuntimeException('asset_type_mismatch');$assetId=$replaceAsset;$assetUuid=$existing['asset_uuid'];$db->prepare('UPDATE media_assets SET title=?,original_name=?,mime_type=?,byte_size=?,width=?,height=?,checksum=?,processing_status="processing",updated_at=? WHERE id=?')->execute([$file['name'],$file['name'],$mime,$file['size'],$w,$h,$checksum,$now,$assetId]);}else{$q=$db->prepare('INSERT INTO media_assets(asset_uuid,kind,title,original_name,mime_type,byte_size,width,height,checksum,processing_status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,"processing",?,?)');$q->execute([$assetUuid,$kind,pathinfo($file['name'],PATHINFO_FILENAME),$file['name'],$mime,$file['size'],$w,$h,$checksum,$now,$now]);$assetId=(int)$db->lastInsertId();}$dir=media_upload_root().'/'.$assetUuid.'/'.$versionUuid.'/original';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('storage_unavailable');$ext=$mime==='image/jpeg'?'jpg':($mime==='image/png'?'png':($mime==='image/webp'?'webp':($mime==='video/mp4'?'mp4':'webm')));$relative=$assetUuid.'/'.$versionUuid.'/original/file.'.$ext;if(!move_uploaded_file($file['tmp_name'],media_upload_root().'/'.$relative))throw new RuntimeException('storage_write_failed');$q=$db->prepare('INSERT INTO media_versions(asset_id,version_uuid,original_path,mime_type,byte_size,width,height,checksum,processing_status,created_at) VALUES(?,?,?,?,?,?,?,?,"processing",?)');$q->execute([$assetId,$versionUuid,$relative,$mime,$file['size'],$w,$h,$checksum,$now]);$versionId=(int)$db->lastInsertId();try{if($kind==='image')media_generate_images($db,$versionId,$relative,$mime,$w,$h);$db->prepare('UPDATE media_versions SET processing_status="ready" WHERE id=?')->execute([$versionId]);$db->prepare('UPDATE media_assets SET active_version_id=?,processing_status="ready",updated_at=? WHERE id=?')->execute([$versionId,$now,$assetId]);}catch(Throwable $e){$db->prepare('UPDATE media_versions SET processing_status="error",error_message=? WHERE id=?')->execute([$e->getMessage(),$versionId]);$db->prepare('UPDATE media_assets SET processing_status="error",updated_at=? WHERE id=?')->execute([$now,$assetId]);throw $e;}return media_asset($db,$assetId);}
function media_generate_images(PDO $db,int $versionId,string $relative,string $mime,?int $w,?int $h):void{$source=media_upload_root().'/'.$relative;if(!$w||!$h||!extension_loaded('gd'))return;$make=match($mime){'image/jpeg'=>'imagecreatefromjpeg','image/png'=>'imagecreatefrompng','image/webp'=>function($p){return function_exists('imagecreatefromwebp')?imagecreatefromwebp($p):false;}};$img=$make($source);if(!$img)throw new RuntimeException('image_processing_failed');$base=dirname(dirname($relative));foreach(MEDIA_IMAGE_WIDTHS as $target){if($target>$w)continue;$height=(int)round($h*$target/$w);$out=imagecreatetruecolor($target,$height);imagealphablending($out,false);imagesavealpha($out,true);$transparent=imagecolorallocatealpha($out,0,0,0,127);imagefill($out,0,0,$transparent);imagecopyresampled($out,$img,0,0,0,0,$target,$height,$w,$h);$dir=media_upload_root().'/'.$base.'/responsive';if(!is_dir($dir))mkdir($dir,0755,true);$path=$base.'/responsive/'.$target.'.jpg';imagejpeg($out,media_upload_root().'/'.$path,84);imagedestroy($out);$db->prepare('INSERT OR REPLACE INTO media_derivatives(version_id,derivative_kind,width,height,format,path,byte_size,created_at) VALUES(?,?,?,?,?,?,?,?)')->execute([$versionId,'responsive',$target,$height,'jpeg',$path,filesize(media_upload_root().'/'.$path),gmdate('c')]);}imagedestroy($img);}
function media_asset(PDO $db,int $id):array{$q=$db->prepare('SELECT a.*,v.original_path,v.version_uuid FROM media_assets a LEFT JOIN media_versions v ON v.id=a.active_version_id WHERE a.id=?');$q->execute([$id]);$a=$q->fetch();if(!$a)throw new RuntimeException('asset_not_found');$q=$db->prepare('SELECT * FROM media_derivatives WHERE version_id=? ORDER BY width');$q->execute([$a['active_version_id']]);$a['derivatives']=$q->fetchAll();$a['url']=media_url($a['original_path']);return $a;}
function media_list(PDO $db):array{$rows=$db->query('SELECT id FROM media_assets WHERE archived_at IS NULL ORDER BY id DESC')->fetchAll();return array_map(fn($r)=>media_asset($db,(int)$r['id']),$rows);}
function media_create_poster(PDO $db,int $assetId,int $versionId,float $timestamp,array $file):array{if(!is_finite($timestamp)||$timestamp<0)throw new RuntimeException('invalid_timestamp');$q=$db->prepare('SELECT a.asset_uuid,a.kind,v.id FROM media_assets a JOIN media_versions v ON v.asset_id=a.id WHERE a.id=? AND v.id=? AND v.processing_status="ready"');$q->execute([$assetId,$versionId]);$video=$q->fetch();if(!$video||$video['kind']!=='video')throw new RuntimeException('invalid_video_version');if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||($file['size']??0)>10*1024*1024)throw new RuntimeException('invalid_frame');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if(!in_array($mime,['image/jpeg','image/png'],true))throw new RuntimeException('invalid_frame_type');$info=@getimagesize($file['tmp_name']);if(!$info||$info[0]<1||$info[1]<1)throw new RuntimeException('invalid_frame');$uuid=bin2hex(random_bytes(16));$now=gmdate('c');$db->beginTransaction();try{$db->prepare('INSERT INTO media_posters(video_asset_id,video_version_id,poster_uuid,timestamp_seconds,source_width,source_height,created_at) VALUES(?,?,?,?,?,?,?)')->execute([$assetId,$versionId,$uuid,$timestamp,$info[0],$info[1],$now]);$id=(int)$db->lastInsertId();$dir=media_upload_root().'/'.$video['asset_uuid'].'/'.$versionId.'/posters/'.$uuid;if(!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('storage_unavailable');$name='poster.jpg';$path=$dir.'/'.$name;if($mime==='image/jpeg')imagejpeg(imagecreatefromjpeg($file['tmp_name']),$path,85);else imagejpeg(imagecreatefrompng($file['tmp_name']),$path,85);$relative=substr($path,strlen(media_upload_root())+1);$db->prepare('INSERT INTO media_poster_variants(poster_id,variant_key,width,height,format,mime_type,path,size_bytes,checksum,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$id,'original',$info[0],$info[1],'jpeg','image/jpeg',$relative,filesize($path),hash_file('sha256',$path),$now]);$db->commit();return ['id'=>$id,'mediaAssetId'=>$assetId,'mediaVersionId'=>$versionId,'timestamp'=>$timestamp,'width'=>$info[0],'height'=>$info[1],'src'=>media_url($relative),'variants'=>[['key'=>'original','format'=>'jpeg','width'=>$info[0],'height'=>$info[1],'src'=>media_url($relative)]]];}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if(isset($dir)&&is_dir($dir))@rmdir($dir);throw $e;}}
